; LPTMOUSE.COM - DOS mouse driver (INT 33h) for a PS/2 mouse wired directly
; to a PC parallel port. See README.md for the cable.
;
; How it reads the mouse
; ----------------------
; The PS/2 clock is generated by the mouse (10-16.7 kHz). We cannot take an
; interrupt per clock edge, so the driver uses the host "inhibit" feature:
; holding CLK low makes the mouse abort and keep its data until CLK is
; released again.
;
;  IRQ mode (default, /I7 or /I5): CLK is released while idle. The mouse's
;  first clock edge raises the port IRQ (CLK is wired to /ACK). The handler
;  holds CLK low to abort that transmission, releases it, and reads the whole
;  packet in a tight loop with interrupts off (~3 ms). So the interrupt
;  latency does not matter, only the polling loop has to keep up with the
;  clock.
;
;  Poll mode (/I0): CLK is held low all the time. On every timer tick (18.2
;  Hz) the driver releases it for a few ms and reads whatever the mouse has.
;  No IRQ needed, but the cursor only updates 18 times a second.
;
; Build: nasm -f bin -o lptmouse.com lptmouse.asm

        cpu 8086
        org 100h

start:  jmp install

signature       db 'LPTMOUSE', 1, 0     ; name + version
SIG_LEN         equ $ - signature

; ===========================================================================
; Resident data
; ===========================================================================

BURST_MAX       equ 9

MT_NONE         equ 0
MT_TEXT         equ 1
MT_PLANAR       equ 2           ; EGA/VGA 16 colours (0Dh, 0Eh, 10h, 12h)
MT_LINEAR       equ 3           ; 1 bpp linear (11h)
MT_CGA          equ 4           ; 1 bpp interleaved (06h)
MT_V256         equ 5           ; 13h

port_data       dw 0
port_status     dw 0
port_ctrl       dw 0
drive_xor       db 0
irq             db 7            ; 0 = poll on the timer tick
ctrl_val        db 04h          ; control register, port IRQ disabled
pic_unmasked    db 0
sample_rate     db 40
hw_vec          db 0            ; vector hooked for the hardware side
old_int33       dd 0
old_int10       dd 0
old_hwint       dd 0

in_service      db 0
in_handler      db 0
enabled         db 1
save_ss         dw 0
save_sp         dw 0

nbytes          dw 0
burst_buf       times BURST_MAX db 0

cnt_packets     dw 0
cnt_errors      dw 0
cnt_sync        dw 0
cnt_resend      dw 0

tot_x           dw 0            ; never reset (passed to the event handler)
tot_y           dw 0
ev_mask         dw 0
new_btn         db 0
chg_btn         db 0

; --- cursor drawing ---
cur_drawn       db 0
cur_kind        db 0
cd_off          dw 0            ; text: offset of the cell
cd_saved        dw 0
cd_written      dw 0
cd_x            dw 0            ; graphics: top-left pixel of the cursor
cd_y            dw 0
bg_buf          times 256 db 0

g_r             dw 0
g_col           dw 0
g_cm            dw 0
g_shift         db 0
g_plane         db 0
g_erase         db 0
g_b0            db 0
g_b1            db 0
g_b2            db 0
g_am            db 0, 0, 0
g_xm            db 0, 0, 0

v_sidx          db 0
v_mm            db 0
v_gidx          db 0
v_gidx_list     db 1, 3, 4, 5, 8
v_gregs         db 0, 0, 0, 0, 0

; --- current video mode ---
mi_type         db 0
mi_planes       db 1
mi_xshift       db 0
mi_cshift       db 3
mi_seg          dw 0
mi_bpl          dw 0
mi_hpix         dw 0
mi_cols         dw 0
mi_rows         dw 0
mi_maxx         dw 0
mi_maxy         dw 0
mi_granx        dw 0
mi_grany        dw 0

; --- driver state (functions 15h-17h save / restore this block) ---
state_start:
pos_x           dw 0
pos_y           dw 0
min_x           dw 0            ; min_x, max_x adjacent (set_range)
max_x           dw 639
min_y           dw 0
max_y           dw 199
gran_x          dw 0FFFFh
gran_y          dw 0FFFFh
buttons         dw 0
cur_level       dw -1           ; 0 = shown, negative = hidden
text_smask      dw 77FFh
text_cmask      dw 7700h
hot_x           dw 0
hot_y           dw 0
ratio_x         dw 8            ; mickeys per 8 pixels
ratio_y         dw 16
dspeed          dw 64
sens_x          dw 50
sens_y          dw 50
sens_dt         dw 50
gfx_masks       times 32 dw 0   ; 16 screen (AND) words, 16 cursor (XOR)
zero_start:
acc_x           dw 0
acc_y           dw 0
mick_x          dw 0
mick_y          dw 0
press_cnt       dw 0, 0, 0      ; cnt, x, y arrays must stay in this order
press_x         dw 0, 0, 0
press_y         dw 0, 0, 0
rel_cnt         dw 0, 0, 0
rel_x           dw 0, 0, 0
rel_y           dw 0, 0, 0
handler_mask    dw 0
handler_ptr     dw 0, 0
vpage           dw 0
zero_end:
state_end:
STATE_SIZE      equ state_end - state_start

default_masks:
        ; screen mask
        dw 3FFFh, 1FFFh, 0FFFh, 07FFh, 03FFh, 01FFh, 00FFh, 007Fh
        dw 003Fh, 001Fh, 01FFh, 10FFh, 30FFh, 0F87Fh, 0F87Fh, 0FC3Fh
        ; cursor mask
        dw 0000h, 4000h, 6000h, 7000h, 7800h, 7C00h, 7E00h, 7F00h
        dw 7F80h, 7C00h, 6C00h, 4600h, 0600h, 0300h, 0300h, 0000h

; ===========================================================================
; Resident code
; ===========================================================================

%include "ps2lpt.inc"
%include "ps2data.inc"

; ---------------------------------------------------------------------------
; Hardware side
; ---------------------------------------------------------------------------

; Port IRQ (CLK activity on /ACK)
irq_isr:
        push ax
        cmp byte [cs:irq], 7
        jne .real
        mov al, 0Bh                 ; read the PIC in-service register
        out 20h, al
        in al, 20h
        mov ah, al
        mov al, 0Ah                 ; back to reading the IRR
        out 20h, al
        test ah, 80h
        jnz .real
        pop ax                      ; spurious IRQ7: no EOI
        iret
.real:
        push dx
        mov dx, [cs:port_ctrl]
        mov al, [cs:ctrl_val]       ; port IRQ off while we toggle CLK
        out dx, al
        call do_service             ; re-enables the port IRQ (hw_rearm)
        cli
        mov al, 20h
        out 20h, al
        pop dx
        pop ax
        iret

; Timer tick (poll mode)
int8_hook:
        pushf
        call far [cs:old_hwint]     ; the BIOS handler sends the EOI
        cli
        push ax
        push dx
        call do_service
        pop dx
        pop ax
        iret

; Reads a burst from the mouse and processes it. Runs on our own stack.
; Called with interrupts off; AX and DX saved by the caller.
do_service:
        cmp byte [cs:in_service], 0
        jne .ret
        mov byte [cs:in_service], 1
        mov [cs:save_ss], ss
        mov [cs:save_sp], sp
        mov ax, cs
        mov ss, ax
        mov sp, stack_top
        push bx
        push cx
        push si
        push di
        push bp
        push ds
        push es
        mov ds, ax
        cld
        call read_burst
        call hw_rearm
        call process_burst
        cli
        pop es
        pop ds
        pop bp
        pop di
        pop si
        pop cx
        pop bx
        mov ss, [cs:save_ss]
        mov sp, [cs:save_sp]
        mov byte [cs:in_service], 0
.ret:   ret

%include "burst.inc"

; IRQ mode: CLK stays released, port IRQ on. Poll mode: hold CLK low.
hw_rearm:
        cmp byte [irq], 0
        jne .irq
        mov al, OUT_CLKLO
        jmp ps2_lines
.irq:   mov dx, [port_ctrl]
        mov al, [ctrl_val]
        or al, 10h
        out dx, al
        ret

process_burst:
        mov ax, [nbytes]
        or ax, ax
        jz .ret
        mov bl, 3
        div bl
        or ah, ah
        jnz .sync
        mov cl, al
        xor ch, ch
        mov si, burst_buf
.pk:    test byte [si], 08h         ; bit 3 is always set in the first byte
        jz .sync
        push cx
        push si
        call process_packet
        pop si
        pop cx
        add si, 3
        loop .pk
.ret:   ret
.sync:  inc word [cnt_sync]
        ret

; SI -> 3-byte packet: flags, dx, dy
process_packet:
        inc word [cnt_packets]
        cmp byte [enabled], 0
        jne .go
        ret
.go:    mov word [ev_mask], 0
        mov al, [si]
        mov bl, [si+1]
        xor bh, bh
        test al, 10h
        jz .x1
        mov bh, 0FFh
.x1:    mov cl, [si+2]
        xor ch, ch
        test al, 20h
        jz .y1
        mov ch, 0FFh
.y1:    neg cx                      ; PS/2 Y grows upwards, screen downwards
        test al, 0C0h               ; overflow: ignore the movement
        jz .nov
        xor bx, bx
        xor cx, cx
.nov:   and al, 7
        mov [new_btn], al
        mov ax, bx
        or ax, cx
        jz .nomove
        or word [ev_mask], 1
        add [mick_x], bx
        add [mick_y], cx
        add [tot_x], bx
        add [tot_y], cx
        ; pixels = mickeys * 8 / ratio, keeping the remainder
        mov ax, bx
        shl ax, 1
        shl ax, 1
        shl ax, 1
        add ax, [acc_x]
        cwd
        idiv word [ratio_x]
        mov [acc_x], dx
        add [pos_x], ax
        mov ax, cx
        shl ax, 1
        shl ax, 1
        shl ax, 1
        add ax, [acc_y]
        cwd
        idiv word [ratio_y]
        mov [acc_y], dx
        add [pos_y], ax
        call clamp_pos
.nomove:
        mov al, [new_btn]
        mov ah, [buttons]
        xor ah, al
        jz .nobtn
        mov [chg_btn], ah
        call rep_xy                 ; CX, DX = reported position
        xor bx, bx                  ; button index * 2
        mov di, 2                   ; press event bit of the button
        mov ah, 1                   ; button bit
.bl:    test [chg_btn], ah
        jz .nc
        test [new_btn], ah
        jz .rel
        inc word [press_cnt + bx]
        mov [press_x + bx], cx
        mov [press_y + bx], dx
        or [ev_mask], di
        jmp .nc
.rel:   inc word [rel_cnt + bx]
        mov [rel_x + bx], cx
        mov [rel_y + bx], dx
        mov si, di
        shl si, 1                   ; release bit = press bit << 1
        or [ev_mask], si
.nc:    add bx, 2
        shl di, 1
        shl di, 1
        shl ah, 1
        cmp bx, 6
        jb .bl
        mov al, [new_btn]
        xor ah, ah
        mov [buttons], ax
.nobtn:
        test word [ev_mask], 1
        jz .nodraw
        cmp word [cur_level], 0
        jne .nodraw
        call cursor_erase
        call cursor_draw
.nodraw:
        ; user event handler (function 0Ch / 14h)
        mov ax, [ev_mask]
        and ax, [handler_mask]
        jz .ret
        cmp byte [in_handler], 0
        jne .ret
        mov cx, [handler_ptr]
        or cx, [handler_ptr + 2]
        jz .ret
        inc byte [in_handler]
        push ds
        push ax
        call rep_xy
        pop ax
        mov bx, [buttons]
        mov si, [tot_x]
        mov di, [tot_y]
        sti
        call far [cs:handler_ptr]
        cli
        pop ds
        dec byte [in_handler]
.ret:   ret

clamp_pos:
        mov ax, [pos_x]
        cmp ax, [min_x]
        jge .a
        mov ax, [min_x]
.a:     cmp ax, [max_x]
        jle .b
        mov ax, [max_x]
.b:     mov [pos_x], ax
        mov ax, [pos_y]
        cmp ax, [min_y]
        jge .c
        mov ax, [min_y]
.c:     cmp ax, [max_y]
        jle .d
        mov ax, [max_y]
.d:     mov [pos_y], ax
        ret

; reported position (snapped to the character cell / pixel) -> CX, DX
rep_xy:
        mov cx, [pos_x]
        and cx, [gran_x]
        mov dx, [pos_y]
        and dx, [gran_y]
        ret

; ---------------------------------------------------------------------------
; INT 10h hook: a mode set clears the screen, forget the drawn cursor and
; hide it (like the Microsoft driver).
; ---------------------------------------------------------------------------
int10_hook:
        or ah, ah
        jnz .chain
        mov byte [cs:cur_drawn], 0
        mov word [cs:cur_level], -1
.chain: jmp far [cs:old_int10]

; ---------------------------------------------------------------------------
; Video mode info
; ---------------------------------------------------------------------------
get_mode_info:
        push es
        mov ax, 40h
        mov es, ax
        mov byte [mi_type], MT_NONE
        mov word [mi_seg], 0A000h
        mov word [mi_bpl], 80
        mov word [mi_hpix], 200
        mov byte [mi_planes], 1
        mov byte [mi_xshift], 0
        mov word [mi_maxx], 639
        mov word [mi_maxy], 199
        mov word [mi_granx], 0FFFFh
        mov word [mi_grany], 0FFFFh
        mov al, [es:49h]
        and al, 7Fh
        cmp al, 3
        jbe .text
        cmp al, 7
        je .mono
        cmp al, 5
        jbe .cga2
        cmp al, 6
        je .cga1
        cmp al, 0Dh
        je .m0d
        cmp al, 0Eh
        je .m0e
        cmp al, 0Fh
        je .m0f
        cmp al, 10h
        je .m10
        cmp al, 11h
        je .m11
        cmp al, 12h
        je .m12
        cmp al, 13h
        je .m13
        jmp .done
.cga2:  mov word [mi_granx], 0FFFEh ; 320x200x4: no cursor drawn
        jmp .done
.cga1:  mov byte [mi_type], MT_CGA
        mov word [mi_seg], 0B800h
        jmp .done
.m0d:   mov byte [mi_type], MT_PLANAR
        mov byte [mi_planes], 4
        mov word [mi_bpl], 40
        mov byte [mi_xshift], 1
        mov word [mi_granx], 0FFFEh
        jmp .done
.m0e:   mov byte [mi_type], MT_PLANAR
        mov byte [mi_planes], 4
        jmp .done
.m0f:   mov word [mi_maxy], 349
        jmp .done
.m10:   mov byte [mi_type], MT_PLANAR
        mov byte [mi_planes], 4
        mov word [mi_hpix], 350
        mov word [mi_maxy], 349
        jmp .done
.m11:   mov byte [mi_type], MT_LINEAR
        mov word [mi_hpix], 480
        mov word [mi_maxy], 479
        jmp .done
.m12:   mov byte [mi_type], MT_PLANAR
        mov byte [mi_planes], 4
        mov word [mi_hpix], 480
        mov word [mi_maxy], 479
        jmp .done
.m13:   mov byte [mi_type], MT_V256
        mov byte [mi_xshift], 1
        mov word [mi_granx], 0FFFEh
        jmp .done
.mono:  mov word [mi_seg], 0B000h
        jmp .text2
.text:  mov word [mi_seg], 0B800h
.text2: mov byte [mi_type], MT_TEXT
        mov ax, [es:4Ah]
        mov [mi_cols], ax
        mov cl, 3
        mov word [mi_granx], 0FFF8h
        cmp ax, 40
        ja .c80
        mov cl, 4                   ; 40 columns: 16 virtual pixels per cell
        mov word [mi_granx], 0FFF0h
.c80:   mov [mi_cshift], cl
        shl ax, cl
        dec ax
        mov [mi_maxx], ax
        mov al, [es:84h]            ; rows - 1 (EGA/VGA BIOS)
        cmp al, 24
        jb .r25
        cmp al, 59
        jbe .rok
.r25:   mov al, 24
.rok:   xor ah, ah
        inc ax
        mov [mi_rows], ax
        mov cl, 3
        shl ax, cl
        dec ax
        mov [mi_maxy], ax
        mov word [mi_grany], 0FFF8h
.done:  pop es
        ret

; ---------------------------------------------------------------------------
; Cursor drawing. All of these clobber AX-DX, SI, DI (not BP).
; ---------------------------------------------------------------------------
cursor_draw:
        cmp byte [enabled], 0
        je .ret
        cmp word [cur_level], 0
        jne .ret
        cmp byte [cur_drawn], 0
        jne .ret
        call get_mode_info
        mov al, [mi_type]
        cmp al, MT_NONE
        je .ret
        mov [cur_kind], al
        cmp al, MT_TEXT
        je text_draw
        call gfx_origin
        mov byte [g_erase], 0
        mov byte [cur_drawn], 1
        cmp byte [mi_type], MT_V256
        je v256_run
        jmp bytes_run
.ret:   ret

cursor_erase:
        cmp byte [cur_drawn], 0
        je .ret
        mov byte [cur_drawn], 0
        mov al, [cur_kind]
        cmp al, MT_TEXT
        je text_erase
        mov byte [g_erase], 1
        cmp al, MT_V256
        je v256_run
        jmp bytes_run
.ret:   ret

text_draw:
        push es
        mov es, [mi_seg]
        call rep_xy
        mov ax, cx
        mov cl, [mi_cshift]
        shr ax, cl
        cmp ax, [mi_cols]
        jae .out
        mov bx, ax                  ; column
        mov ax, dx
        mov cl, 3
        shr ax, cl
        cmp ax, [mi_rows]
        jae .out
        mul word [mi_cols]
        add ax, bx
        shl ax, 1
        push ds
        mov bx, 40h
        mov ds, bx
        add ax, [4Eh]               ; start of the active page
        pop ds
        mov bx, ax
        mov [cd_off], bx
        mov ax, [es:bx]
        mov [cd_saved], ax
        and ax, [text_smask]
        xor ax, [text_cmask]
        mov [es:bx], ax
        mov [cd_written], ax
        mov byte [cur_drawn], 1
.out:   pop es
        ret

text_erase:
        push es
        mov es, [mi_seg]
        mov bx, [cd_off]
        mov ax, [es:bx]
        cmp ax, [cd_written]        ; overwritten by the program: leave it
        jne .x
        mov ax, [cd_saved]
        mov [es:bx], ax
.x:     pop es
        ret

; top-left pixel of the cursor -> cd_x, cd_y
gfx_origin:
        call rep_xy
        mov ax, cx
        mov cl, [mi_xshift]
        shr ax, cl
        sub ax, [hot_x]
        mov [cd_x], ax
        mov ax, dx
        sub ax, [hot_y]
        mov [cd_y], ax
        ret

; mode 13h: one byte per pixel. g_erase = 0 draw, 1 restore.
v256_run:
        push es
        mov ax, 0A000h
        mov es, ax
        mov word [g_r], 0
        mov bx, bg_buf
.row:   mov ax, [cd_y]
        add ax, [g_r]
        cmp ax, 200
        jae .skiprow                ; also skips negative rows
        mov cl, 6
        shl ax, cl                  ; y * 64
        mov di, ax
        shl ax, 1
        shl ax, 1                   ; y * 256
        add di, ax
        add di, [cd_x]
        mov si, [g_r]
        shl si, 1
        mov ax, [gfx_masks + 32 + si]
        mov [g_cm], ax
        mov si, [gfx_masks + si]
        mov dx, [cd_x]
        mov cx, 16
.col:   xor ah, ah
        shl si, 1
        adc ah, 0                   ; bit 0 = screen mask bit
        shl word [g_cm], 1
        jnc .c0
        or ah, 2                    ; bit 1 = cursor mask bit
.c0:    cmp dx, 320
        jae .nx
        cmp byte [g_erase], 0
        jne .er
        mov al, [es:di]
        mov [bx], al
        test ah, 1
        jnz .keep
        xor al, al
.keep:  test ah, 2
        jz .w
        xor al, 0Fh
.w:     mov [es:di], al
        jmp .nx
.er:    mov al, [bx]
        mov [es:di], al
.nx:    inc bx
        inc di
        inc dx
        loop .col
        jmp .nextrow
.skiprow:
        add bx, 16
.nextrow:
        inc word [g_r]
        cmp word [g_r], 16
        jb .row
        pop es
        ret

; AX = 16-bit mask row, [g_shift] -> the three bytes it covers: g_b0..g_b2
split_mask:
        mov dx, ax
        mov cl, [g_shift]
        shr ax, cl
        mov [g_b0], ah
        mov [g_b1], al
        mov al, dl
        mov cl, 8
        sub cl, [g_shift]
        shl al, cl
        mov [g_b2], al
        ret

; AX = y -> DI = offset of the row
row_offset:
        cmp byte [mi_type], MT_CGA
        je .cga
        mul word [mi_bpl]
        mov di, ax
        ret
.cga:   mov di, ax
        shr ax, 1
        mov dx, 80
        mul dx
        test di, 1
        mov di, ax
        jz .e
        add di, 2000h               ; odd rows
.e:     ret

; 1 bit per pixel per plane (planar EGA/VGA, mode 11h, CGA mode 6)
bytes_run:
        push es
        mov es, [mi_seg]
        mov ax, [cd_x]
        mov cl, 3
        sar ax, cl
        mov [g_col], ax
        mov al, [cd_x]
        and al, 7
        mov [g_shift], al
        cmp byte [mi_type], MT_PLANAR
        jne .np
        call vga_save
.np:    mov byte [g_plane], 0
        mov bx, bg_buf
.plane: cmp byte [mi_type], MT_PLANAR
        jne .rows
        mov dx, 3CEh                ; read map select
        mov al, 4
        mov ah, [g_plane]
        out dx, ax
        mov dx, 3C4h                ; map mask
        mov cl, [g_plane]
        mov ah, 1
        shl ah, cl
        mov al, 2
        out dx, ax
.rows:  mov word [g_r], 0
.row:   mov ax, [cd_y]
        add ax, [g_r]
        cmp ax, [mi_hpix]
        jae .skiprow
        call row_offset
        mov si, [g_r]
        shl si, 1
        mov ax, [gfx_masks + 32 + si]
        call split_mask
        mov al, [g_b0]
        mov [g_xm], al
        mov al, [g_b1]
        mov [g_xm + 1], al
        mov al, [g_b2]
        mov [g_xm + 2], al
        mov ax, [gfx_masks + si]
        not ax
        call split_mask
        mov al, [g_b0]
        not al
        mov [g_am], al
        mov al, [g_b1]
        not al
        mov [g_am + 1], al
        mov al, [g_b2]
        not al
        mov [g_am + 2], al
        mov dx, [g_col]
        mov cx, 3
        xor si, si
.byte:  cmp dx, [mi_bpl]
        jae .nb                     ; also skips negative columns
        push di
        add di, dx
        cmp byte [g_erase], 0
        jne .er
        mov al, [es:di]
        mov [bx], al
        and al, [g_am + si]
        xor al, [g_xm + si]
        mov [es:di], al
        jmp .wd
.er:    mov al, [bx]
        mov [es:di], al
.wd:    pop di
.nb:    inc bx
        inc si
        inc dx
        loop .byte
        jmp .nextrow
.skiprow:
        add bx, 3
.nextrow:
        inc word [g_r]
        cmp word [g_r], 16
        jb .row
        inc byte [g_plane]
        mov al, [g_plane]
        cmp al, [mi_planes]
        jb .plane
        cmp byte [mi_type], MT_PLANAR
        jne .done
        call vga_restore
.done:  pop es
        ret

; Save the VGA registers we touch and set write mode 0, replace, all bits.
; (VGA only: EGA registers cannot be read back.)
vga_save:
        mov dx, 3C4h
        in al, dx
        mov [v_sidx], al
        mov al, 2
        out dx, al
        inc dx
        in al, dx
        mov [v_mm], al
        mov dx, 3CEh
        in al, dx
        mov [v_gidx], al
        mov si, v_gidx_list
        mov di, v_gregs
        mov cx, 5
.l:     mov al, [si]
        out dx, al
        inc dx
        in al, dx
        mov [di], al
        dec dx
        inc si
        inc di
        loop .l
        mov ax, 0001h               ; set/reset enable off
        out dx, ax
        mov ax, 0003h               ; no rotate, replace
        out dx, ax
        mov ax, 0005h               ; write mode 0, read mode 0
        out dx, ax
        mov ax, 0FF08h              ; bit mask: all
        out dx, ax
        ret

vga_restore:
        mov dx, 3CEh
        mov si, v_gidx_list
        mov di, v_gregs
        mov cx, 5
.l:     mov al, [si]
        mov ah, [di]
        out dx, ax
        inc si
        inc di
        loop .l
        mov al, [v_gidx]
        out dx, al
        mov dx, 3C4h
        mov al, 2
        mov ah, [v_mm]
        out dx, ax
        mov al, [v_sidx]
        out dx, al
        ret

; ---------------------------------------------------------------------------
; INT 33h
; ---------------------------------------------------------------------------
R_AX    equ 0
R_BX    equ 2
R_CX    equ 4
R_DX    equ 6
R_SI    equ 8
R_DI    equ 10
R_ES    equ 16

int33:
        push es
        push ds
        push bp
        push di
        push si
        push dx
        push cx
        push bx
        push ax
        mov bp, sp
        push cs
        pop ds
        cld
        cmp ax, FN_COUNT
        jae .done
        mov bx, ax
        shl bx, 1
        call [fn_table + bx]
.done:  pop ax
        pop bx
        pop cx
        pop dx
        pop si
        pop di
        pop bp
        pop ds
        pop es
        iret

fn_table:
        dw fn00, fn01, fn02, fn03, fn04, fn05, fn06, fn07   ; 00-07
        dw fn08, fn09, fn0a, fn0b, fn0c, fn_nop, fn_nop, fn0f ; 08-0F
        dw fn10, fn_nop, fn_nop, fn13, fn14, fn15, fn16, fn17 ; 10-17
        dw fn_nop, fn_nop, fn1a, fn1b, fn_nop, fn1d, fn1e, fn1f ; 18-1F
        dw fn20, fn00, fn_nop, fn_nop, fn24, fn_nop, fn26    ; 20-26
FN_COUNT equ ($ - fn_table) / 2

fn_nop: ret

; reset (00h) / software reset (21h)
fn00:
        call reset_soft
        mov word [bp + R_AX], 0FFFFh
        mov word [bp + R_BX], 2
        ret

reset_soft:
        call cursor_erase
        call get_mode_info
        xor ax, ax
        mov [min_x], ax
        mov [min_y], ax
        mov ax, [mi_maxx]
        mov [max_x], ax
        inc ax
        shr ax, 1
        mov [pos_x], ax
        mov ax, [mi_maxy]
        mov [max_y], ax
        inc ax
        shr ax, 1
        mov [pos_y], ax
        mov ax, [mi_granx]
        mov [gran_x], ax
        mov ax, [mi_grany]
        mov [gran_y], ax
        push es
        push ds
        pop es
        mov di, zero_start
        mov cx, (zero_end - zero_start) / 2
        xor ax, ax
        rep stosw
        mov si, default_masks
        mov di, gfx_masks
        mov cx, 32
        rep movsw
        pop es
        mov word [ratio_x], 8
        mov word [ratio_y], 16
        mov word [dspeed], 64
        mov word [cur_level], -1
        mov word [text_smask], 77FFh
        mov word [text_cmask], 7700h
        mov word [hot_x], 0
        mov word [hot_y], 0
        ret

fn01:   ; show cursor
        mov ax, [cur_level]
        or ax, ax
        jz .r
        inc ax
        mov [cur_level], ax
        jnz .r
        call cursor_draw
.r:     ret

fn02:   ; hide cursor
        cmp word [cur_level], 0
        jne .d
        call cursor_erase
.d:     dec word [cur_level]
        ret

fn03:   ; position and buttons
        mov ax, [buttons]
        mov [bp + R_BX], ax
        call rep_xy
        mov [bp + R_CX], cx
        mov [bp + R_DX], dx
        ret

fn04:   ; set position
        call cursor_erase
        mov ax, [bp + R_CX]
        mov [pos_x], ax
        mov ax, [bp + R_DX]
        mov [pos_y], ax
        xor ax, ax
        mov [acc_x], ax
        mov [acc_y], ax
        call clamp_pos
        jmp cursor_draw

fn05:   ; button press data
        mov si, press_cnt
        jmp btn_info
fn06:   ; button release data
        mov si, rel_cnt
btn_info:
        mov ax, [buttons]
        mov [bp + R_AX], ax
        mov bx, [bp + R_BX]
        cmp bx, 2
        ja .bad
        shl bx, 1
        add si, bx
        xor ax, ax
        xchg ax, [si]
        mov [bp + R_BX], ax
        mov ax, [si + 6]
        mov [bp + R_CX], ax
        mov ax, [si + 12]
        mov [bp + R_DX], ax
        ret
.bad:   xor ax, ax
        mov [bp + R_BX], ax
        mov [bp + R_CX], ax
        mov [bp + R_DX], ax
        ret

fn07:   ; horizontal range
        mov si, min_x
        jmp set_range
fn08:   ; vertical range
        mov si, min_y
set_range:
        mov ax, [bp + R_CX]
        mov dx, [bp + R_DX]
        cmp ax, dx
        jle .ok
        xchg ax, dx
.ok:    mov [si], ax
        mov [si + 2], dx
        call cursor_erase
        call clamp_pos
        jmp cursor_draw

fn09:   ; graphics cursor shape
        call cursor_erase
        mov ax, [bp + R_BX]
        mov [hot_x], ax
        mov ax, [bp + R_CX]
        mov [hot_y], ax
        push ds
        push es
        mov si, [bp + R_DX]
        push cs
        pop es
        mov di, gfx_masks
        mov ds, [bp + R_ES]
        mov cx, 32
        rep movsw
        pop es
        pop ds
        jmp cursor_draw

fn0a:   ; text cursor
        call cursor_erase
        cmp word [bp + R_BX], 0
        jne .hw
        mov ax, [bp + R_CX]
        mov [text_smask], ax
        mov ax, [bp + R_DX]
        mov [text_cmask], ax
        jmp cursor_draw
.hw:    mov word [text_smask], 77FFh  ; hardware cursor: use the default
        mov word [text_cmask], 7700h
        jmp cursor_draw

fn0b:   ; motion counters
        xor ax, ax
        xchg ax, [mick_x]
        mov [bp + R_CX], ax
        xor ax, ax
        xchg ax, [mick_y]
        mov [bp + R_DX], ax
        ret

fn0c:   ; event handler
        mov ax, [bp + R_CX]
        mov [handler_mask], ax
        mov ax, [bp + R_DX]
        mov [handler_ptr], ax
        mov ax, [bp + R_ES]
        mov [handler_ptr + 2], ax
        ret

fn0f:   ; mickey / pixel ratio
        mov ax, [bp + R_CX]
        or ax, ax
        jz .y
        mov [ratio_x], ax
.y:     mov ax, [bp + R_DX]
        or ax, ax
        jz .r
        mov [ratio_y], ax
.r:     ret

fn10:   ; conditional off: simplified to "hide if shown"
        cmp word [cur_level], 0
        jne .r
        jmp fn02
.r:     ret

fn13:   ; double speed threshold (stored only)
        mov ax, [bp + R_DX]
        mov [dspeed], ax
        ret

fn14:   ; swap event handler
        mov ax, [handler_mask]
        xchg ax, [bp + R_CX]
        mov [handler_mask], ax
        mov ax, [handler_ptr]
        xchg ax, [bp + R_DX]
        mov [handler_ptr], ax
        mov ax, [handler_ptr + 2]
        xchg ax, [bp + R_ES]
        mov [handler_ptr + 2], ax
        ret

fn15:   ; state buffer size
        mov word [bp + R_BX], STATE_SIZE
        ret

fn16:   ; save state to ES:DX
        mov di, [bp + R_DX]
        mov si, state_start
        mov cx, STATE_SIZE
        rep movsb
        ret

fn17:   ; restore state from ES:DX
        call cursor_erase
        push ds
        push es
        push cs
        pop es
        mov di, state_start
        mov si, [bp + R_DX]
        mov ds, [bp + R_ES]
        mov cx, STATE_SIZE
        rep movsb
        pop es
        pop ds
        jmp cursor_draw

fn1a:   ; set sensitivity (stored only)
        mov ax, [bp + R_BX]
        mov [sens_x], ax
        mov ax, [bp + R_CX]
        mov [sens_y], ax
        mov ax, [bp + R_DX]
        mov [sens_dt], ax
        ret

fn1b:
        mov ax, [sens_x]
        mov [bp + R_BX], ax
        mov ax, [sens_y]
        mov [bp + R_CX], ax
        mov ax, [sens_dt]
        mov [bp + R_DX], ax
        ret

fn1d:   ; display page (stored; the active BIOS page is used)
        mov ax, [bp + R_BX]
        mov [vpage], ax
        ret

fn1e:
        mov ax, [vpage]
        mov [bp + R_BX], ax
        ret

fn1f:   ; disable driver
        call cursor_erase
        mov byte [enabled], 0
        mov word [bp + R_AX], 001Fh
        mov ax, [old_int33]
        mov [bp + R_BX], ax
        mov ax, [old_int33 + 2]
        mov [bp + R_ES], ax
        ret

fn20:   ; enable driver
        mov byte [enabled], 1
        jmp cursor_draw

fn24:   ; version: 6.26, PS/2 type
        mov word [bp + R_BX], 0626h
        mov word [bp + R_CX], 0400h
        ret

fn26:   ; maximum coordinates
        mov word [bp + R_BX], 0
        mov ax, [max_x]
        mov [bp + R_CX], ax
        mov ax, [max_y]
        mov [bp + R_DX], ax
        ret

; resident stack for the interrupt side
        align 2
stack_area      times 384 db 0
stack_top:

resident_end:

; ===========================================================================
; Transient part: installation
; ===========================================================================

%include "util.inc"
%include "dosplat.inc"
%include "ps2init.inc"

opt_port        dw 0
opt_irq         db 0FFh
opt_uninst      db 0
opt_status      db 0
init_trace      db 0
res_seg         dw 0

msg_banner  db 'LPTMOUSE 1.0 - PS/2 mouse on the parallel port', 13, 10, 0
msg_usage   db 'Usage: LPTMOUSE [/Ln | /Pxxx] [/In] [/Rnn] [/X] [/V] [/U] [/S]', 13, 10
            db '  /L1../L3  use LPTn (default LPT1)', 13, 10
            db '  /Pxxx     port address in hex, e.g. /P378', 13, 10
            db '  /In       IRQ of the port, 2-7 (default 7, 5 for 278h)', 13, 10
            db '            /I0 = no IRQ, poll on the timer tick (18 Hz)', 13, 10
            db '  /Rnn      sample rate 10,20,40,60,80,100,200 (default 40)', 13, 10
            db '  /X        inverting line driver (transistors, 74LS05)', 13, 10
            db '  /V        show the mouse replies while initialising', 13, 10
            db '  /U        uninstall', 13, 10
            db '  /S        show status and counters', 13, 10, 0
msg_already db 'LPTMOUSE is already installed.', 13, 10, 0
msg_other   db 'Another mouse driver is installed.', 13, 10, 0
msg_noport  db 'No parallel port found (use /Lx or /Pxxx).', 13, 10, 0
msg_port    db 'Port ', 0
msg_irq     db 'h, IRQ ', 0
msg_poll    db 'h, no IRQ (timer polling)', 0
msg_rate    db ', sample rate ', 0
msg_lines   db 'Checking the cable... ', 0
msg_ok      db 'ok', 13, 10, 0
msg_reset   db 'Resetting the mouse... ', 0
msg_installed db 'Driver installed.', 13, 10, 0
msg_notinst db 'LPTMOUSE is not installed.', 13, 10, 0
msg_cantun  db 'Cannot uninstall: interrupt vectors were hooked by another program.', 13, 10, 0
msg_removed db 'LPTMOUSE removed.', 13, 10, 0
msg_packets db 'Packets: ', 0
msg_errors  db ', frame errors: ', 0
msg_syncs   db ', dropped bursts: ', 0
msg_resends db ', resends: ', 0
msg_speed   db 'Port reads per ms: ', 0
msg_pos     db 'Position: ', 0

line_errs   dw le1, le2, le3, le4, le5
le1 db 'CLK (pin 10) is low with nothing driving it: mouse not powered, or no pull-up.', 13, 10, 0
le2 db 'DATA (pin 13) is low with nothing driving it: mouse not powered, or no pull-up.', 13, 10, 0
le3 db 'D0 (pin 2) cannot pull CLK low: check the diode and the pin 2 / pin 10 wiring.', 13, 10, 0
le4 db 'D1 (pin 3) cannot pull DATA low: check the diode and the pin 3 / pin 13 wiring.', 13, 10, 0
le5 db 'CLK and DATA move together: the lines are shorted or swapped.', 13, 10, 0

init_errs   dw ie1, ie2, ie3, ie4
ie1 db 'no reply to reset. Is a PS/2 mouse connected?', 13, 10, 0
ie2 db 'no self-test result from the mouse.', 13, 10, 0
ie3 db 'the mouse rejected the sample rate.', 13, 10, 0
ie4 db 'the mouse rejected the enable command.', 13, 10, 0

valid_rates db 10, 20, 40, 60, 80, 100, 200, 0

install:
        cld
        mov si, msg_banner
        call print_str
        call parse_args
        jnc .args_ok
        mov si, msg_usage
        call print_str
        mov ax, 4C01h
        int 21h
.args_ok:
        call find_resident
        cmp byte [opt_uninst], 0
        jne do_uninstall
        cmp byte [opt_status], 0
        jne do_status
        cmp word [res_seg], 0
        je .not_res
        mov si, msg_already
        jmp fail_msg
.not_res:
        ; another INT 33h driver?
        mov ax, 3533h
        int 21h
        mov ax, es
        or ax, bx
        jz .no_other
        cmp byte [es:bx], 0CFh      ; IRET stub
        je .no_other
        xor ax, ax
        int 33h
        cmp ax, 0FFFFh
        jne .no_other
        mov si, msg_other
        jmp fail_msg
.no_other:
        push cs
        pop es
        call select_port
        jnc .port_ok
        mov si, msg_noport
        jmp fail_msg
.port_ok:
        mov ax, [port_data]
        add ax, 2
        mov [port_ctrl], ax
        mov al, [opt_irq]
        cmp al, 0FFh
        jne .irq_set
        mov al, 7
        cmp word [port_data], 278h
        jne .irq_set
        mov al, 5
.irq_set:
        mov [irq], al

        mov si, msg_port
        call print_str
        mov ax, [port_data]
        call print_hex16
        cmp byte [irq], 0
        jne .pirq
        mov si, msg_poll
        call print_str
        jmp .prate
.pirq:  mov si, msg_irq
        call print_str
        mov al, [irq]
        xor ah, ah
        call print_dec
.prate: mov si, msg_rate
        call print_str
        mov al, [sample_rate]
        xor ah, ah
        call print_dec
        call print_crlf

        ; control register: outputs enabled, port IRQ off
        mov dx, [port_ctrl]
        mov al, [ctrl_val]
        out dx, al

        call calibrate_timeouts
        mov si, msg_lines
        call print_str
        call line_test
        jnc .lines_ok
        call print_crlf
        mov bl, al
        dec bl
        xor bh, bh
        shl bx, 1
        mov si, [line_errs + bx]
        jmp fail_msg
.lines_ok:
        mov si, msg_ok
        call print_str

        mov si, msg_reset
        call print_str
        call mouse_init
        jnc .init_ok
        mov bl, al
        dec bl
        xor bh, bh
        shl bx, 1
        mov si, [init_errs + bx]
        jmp fail_msg
.init_ok:
        mov si, msg_ok
        call print_str

        call reset_soft

        ; hook the vectors
        cli
        mov ax, 3533h
        int 21h
        mov [old_int33], bx
        mov [old_int33 + 2], es
        mov dx, int33
        mov ax, 2533h
        int 21h

        mov ax, 3510h
        int 21h
        mov [old_int10], bx
        mov [old_int10 + 2], es
        mov dx, int10_hook
        mov ax, 2510h
        int 21h

        cmp byte [irq], 0
        jne .hook_irq
        mov byte [hw_vec], 08h
        mov ax, 3508h
        int 21h
        mov [old_hwint], bx
        mov [old_hwint + 2], es
        mov dx, int8_hook
        mov ax, 2508h
        int 21h
        jmp .hooked                 ; CLK stays inhibited (mouse_init)
.hook_irq:
        mov al, [irq]
        add al, 8
        mov [hw_vec], al
        mov ah, 35h
        int 21h
        mov [old_hwint], bx
        mov [old_hwint + 2], es
        mov dx, irq_isr
        mov al, [hw_vec]
        mov ah, 25h
        int 21h
        mov al, OUT_IDLE            ; release CLK: the mouse may talk now
        call ps2_lines
        mov dx, [port_ctrl]
        mov al, [ctrl_val]
        or al, 10h                  ; port IRQ on
        out dx, al
        mov cl, [irq]
        mov ah, 1
        shl ah, cl
        in al, 21h
        test al, ah
        jz .unmasked
        mov byte [pic_unmasked], 1
        not ah
        and al, ah
        out 21h, al
.unmasked:
.hooked:
        sti
        mov si, msg_installed
        call print_str

        ; free the environment and stay resident
        mov es, [2Ch]
        mov ah, 49h
        int 21h
        mov dx, (resident_end - $$ + 100h + 15) / 16
        mov ax, 3100h
        int 21h

fail_msg:
        call print_str
        mov ax, 4C01h
        int 21h

; ES = segment of the resident copy, CF=1 if not found
find_resident:
        mov ax, 3533h
        int 21h
        mov ax, es
        or ax, ax
        jz .nf
        mov si, signature
        mov di, signature
        mov cx, SIG_LEN
        repe cmpsb
        jne .nf
        mov [res_seg], es
        clc
        ret
.nf:    stc
        ret

do_uninstall:
        cmp word [res_seg], 0
        jne .found
        mov si, msg_notinst
        jmp fail_msg
.found:
        mov ax, 3533h
        int 21h
        mov ax, es
        cmp ax, [res_seg]
        jne .cant
        mov ax, 3510h
        int 21h
        mov ax, es
        cmp ax, [res_seg]
        jne .cant
        mov es, [res_seg]
        mov al, [es:hw_vec]
        mov ah, 35h
        int 21h
        mov ax, es
        cmp ax, [res_seg]
        je .ok
.cant:  mov si, msg_cantun
        jmp fail_msg
.ok:
        mov es, [res_seg]
        cli
        cmp byte [es:irq], 0
        je .noirq
        cmp byte [es:pic_unmasked], 0
        je .nomask
        mov cl, [es:irq]
        mov ah, 1
        shl ah, cl
        in al, 21h
        or al, ah
        out 21h, al
.nomask:
        mov dx, [es:port_ctrl]
        mov al, [es:ctrl_val]
        out dx, al
.noirq:
        mov dx, [es:port_data]      ; keep the mouse quiet
        mov al, OUT_CLKLO
        xor al, [es:drive_xor]
        out dx, al
        push ds
        lds dx, [es:old_int33]
        mov ax, 2533h
        int 21h
        pop ds
        push ds
        lds dx, [es:old_int10]
        mov ax, 2510h
        int 21h
        pop ds
        push ds
        mov al, [es:hw_vec]
        lds dx, [es:old_hwint]
        mov ah, 25h
        int 21h
        pop ds
        sti
        mov ah, 49h                 ; ES = resident segment
        int 21h
        mov si, msg_removed
        call print_str
        mov ax, 4C00h
        int 21h

do_status:
        cmp word [res_seg], 0
        jne .found
        mov si, msg_notinst
        jmp fail_msg
.found:
        mov es, [res_seg]
        mov si, msg_port
        call print_str
        mov ax, [es:port_data]
        call print_hex16
        cmp byte [es:irq], 0
        jne .pirq
        mov si, msg_poll
        call print_str
        jmp .prate
.pirq:  mov si, msg_irq
        call print_str
        mov al, [es:irq]
        xor ah, ah
        call print_dec
.prate: mov si, msg_rate
        call print_str
        mov al, [es:sample_rate]
        xor ah, ah
        call print_dec
        call print_crlf
        mov si, msg_packets
        call print_str
        mov ax, [es:cnt_packets]
        call print_dec
        mov si, msg_errors
        call print_str
        mov ax, [es:cnt_errors]
        call print_dec
        mov si, msg_syncs
        call print_str
        mov ax, [es:cnt_sync]
        call print_dec
        mov si, msg_resends
        call print_str
        mov ax, [es:cnt_resend]
        call print_dec
        call print_crlf
        mov si, msg_speed
        call print_str
        mov ax, [es:reads_per_ms]
        call print_dec
        call print_crlf
        mov si, msg_pos
        call print_str
        mov ax, [es:pos_x]
        call print_dec
        mov al, ','
        call print_char
        mov ax, [es:pos_y]
        call print_dec
        call print_crlf
        mov ax, 4C00h
        int 21h

; Parse the command tail. CF=1 on a bad option.
parse_args:
        mov si, 81h
.l:     lodsb
        cmp al, 13
        je .end
        cmp al, ' '
        je .l
        cmp al, 9
        je .l
        cmp al, '/'
        je .opt
        cmp al, '-'
        je .opt
        jmp .bad
.opt:   lodsb
        cmp al, 'a'
        jb .up
        cmp al, 'z'
        ja .up
        sub al, 20h
.up:    call parse_port_opt
        jnc .l
        cmp al, 'I'
        je .irq
        cmp al, 'R'
        je .rate
        cmp al, 'X'
        je .x
        cmp al, 'V'
        je .v
        cmp al, 'U'
        je .u
        cmp al, 'S'
        je .s
        jmp .bad
.irq:   call skip_sep
        call parse_dec
        jc .bad
        cmp ax, 7
        ja .bad
        cmp ax, 1
        je .bad
        mov [opt_irq], al
        jmp .l
.rate:  call skip_sep
        call parse_dec
        jc .bad
        or ah, ah
        jnz .bad
        mov bx, valid_rates
.rl:    mov ah, [bx]
        or ah, ah
        jz .bad
        cmp ah, al
        je .rok
        inc bx
        jmp .rl
.rok:   mov [sample_rate], al
        jmp .l
.x:     mov byte [drive_xor], 3
        jmp .l
.v:     mov byte [init_trace], 1
        jmp .l
.u:     mov byte [opt_uninst], 1
        jmp .l
.s:     mov byte [opt_status], 1
        jmp .l
.end:   clc
        ret
.bad:   stc
        ret
